/* jquery.min.js — minimal shim */
window.$ = window.jQuery = (function () {
  function jQ(sel) {
    if (!(this instanceof jQ)) return new jQ(sel);
    if (typeof sel === 'function') { document.readyState !== 'loading' ? sel() : document.addEventListener('DOMContentLoaded', sel); return this; }
    if (typeof sel === 'string') this.els = Array.from(document.querySelectorAll(sel));
    else if (sel && (sel.nodeType || sel === window || sel === document)) this.els = [sel];
    else this.els = [];
    this.length = this.els.length;
    return this;
  }
  jQ.prototype = {
    each: function(fn) { this.els.forEach((el,i) => fn.call(el,i,el)); return this; },
    on:   function(ev,fn) { this.els.forEach(el => el.addEventListener(ev,fn)); return this; },
    off:  function(ev,fn) { this.els.forEach(el => el.removeEventListener(ev,fn)); return this; },
    addClass:    function(c) { this.els.forEach(el => el.classList.add(c)); return this; },
    removeClass: function(c) { this.els.forEach(el => el.classList.remove(c)); return this; },
    hasClass:    function(c) { return this.els[0] ? this.els[0].classList.contains(c) : false; },
    css: function(p,v) { if(v!==undefined){ this.els.forEach(el=>el.style[p]=v); return this; } return this.els[0]?getComputedStyle(this.els[0])[p]:''; },
    html: function(v) { if(v!==undefined){ this.els.forEach(el=>el.innerHTML=v); return this; } return this.els[0]?this.els[0].innerHTML:''; },
    text: function(v) { if(v!==undefined){ this.els.forEach(el=>el.textContent=v); return this; } return this.els[0]?this.els[0].textContent:''; },
    attr: function(a,v) { if(v!==undefined){ this.els.forEach(el=>el.setAttribute(a,v)); return this; } return this.els[0]?this.els[0].getAttribute(a):null; },
    find: function(sel) { var r=new jQ(null); r.els=[]; this.els.forEach(el=>r.els.push(...Array.from(el.querySelectorAll(sel)))); r.length=r.els.length; return r; },
    scrollTop: function(v) { if(v!==undefined){ window.scrollTo({top:v,behavior:'smooth'}); return this; } return window.scrollY; },
    animate: function(props, dur) { this.els.forEach(el => { el.style.transition = `all ${(dur||400)/1000}s`; Object.assign(el.style, props); }); return this; },
    vegas: function() { return this; },
    sticky: function() { return this; },
  };
  jQ.fn = jQ.prototype;
  jQ.extend = Object.assign;
  jQ.noop = function(){};
  return jQ;
})();